```tsx
// components/Navbar.tsx
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

const NAV_HEIGHT = 72;

const links = [
  { href: "#servicios", label: "Servicios" },
  { href: "#proyectos", label: "Proyectos" },
  { href: "#contacto", label: "Contacto" },
];

type NavbarProps = {
  heroId?: string;
};

export function Navbar({ heroId = "hero" }: NavbarProps) {
  const [hasPassedHero, setHasPassedHero] = useState(false);

  useEffect(() => {
    const hero = document.getElementById(heroId);

    if (!hero) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        setHasPassedHero(
          entry.boundingClientRect.bottom <= NAV_HEIGHT,
        );
      },
      {
        threshold: 0,
        rootMargin: `-${NAV_HEIGHT}px 0px 0px`,
      },
    );

    observer.observe(hero);

    return () => observer.disconnect();
  }, [heroId]);

  return (
    <header
      data-passed-hero={hasPassedHero}
      className={[
        "fixed inset-x-0 top-0 z-50 h-[72px]",
        "border-b transition-[background-color,border-color,box-shadow,backdrop-filter]",
        "duration-300 ease-out motion-reduce:transition-none",
        hasPassedHero
          ? "border-foreground/10 bg-background/90 shadow-[0_12px_36px_rgb(0_0_0/0.10)] backdrop-blur-xl"
          : "border-transparent bg-transparent shadow-none",
      ].join(" ")}
    >
      <nav
        aria-label="Navegación principal"
        className="mx-auto flex h-full max-w-7xl items-center justify-between px-5 md:px-8"
      >
        <Link
          href="/"
          aria-label="Ir al inicio"
          className="text-lg font-semibold tracking-[-0.03em]"
        >
          Marca
        </Link>

        <ul className="flex items-center gap-1">
          {links.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                className="flex min-h-11 items-center rounded-full px-4 text-sm transition-colors duration-200 hover:bg-foreground/8 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-current"
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>
      </nav>
    </header>
  );
}
```

El hero debe exponer el mismo identificador:

```tsx
<section id="hero" className="min-h-svh">
  {/* contenido */}
</section>
```

Usa `IntersectionObserver`, así que no instala un listener de `scroll` ni provoca renders en cada frame. Los tokens `background` y `foreground` quedan delegados al tema Tailwind v4 del proyecto.
